#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

int main() {
    int n;
    std::cin >> n;
    std::vector<char> buf(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> buf[i];
    }
    std::string s(buf.begin(), buf.end());

    int maxSequence = 0, closeCount = 0, openCount = 0, maxOpen = 0;
    int temp = 0, tempCount = 0;

    for (int i = 0; i < n; ++i) {
        char ch = s[i];
        if (ch == '(' || ch == ')' || ch == '_') {
            if (temp > 0) {
                if (tempCount > 0)
                    closeCount++;
                else
                    maxOpen = std::max(temp, maxOpen);
                temp = 0;
            }
            if (ch == '(')
                tempCount = 1;
            if (ch == ')')
                tempCount = 0;
        } else {
            temp++;
        }
    }
    maxSequence = std::max(maxSequence, temp);
    std::cout << maxSequence << " " << closeCount << std::endl;
    return 0;
}

